{"source":"import csv
import sys
import json
import re

def normalize_item(name):
    # Casefold
    name = name.casefold()
    # Collapse whitespace to single spaces
    # split() without arguments splits by any whitespace and removes leading/trailing
    parts = name.split()
    normalized = " ".join(parts)
    return normalized

def solve():
    if len(sys.argv) < 2:
        return

    input_file = sys.argv[1]
    data = {}

    try:
        with open(input_file, mode='r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            for row in reader:
                raw_item = row.get('item', '')
                raw_qty = row.get('quantity', '')

                norm_item = normalize_item(raw_item)

                if not norm_item:
                    continue

                # Quantity handling
                if raw_qty.strip() == '':
                    qty = 1
                else:
                    try:
                        qty = int(raw_qty)
                    except ValueError:
                        # The prompt says "other quantities are nonnegative base-10 integers"
                        # This implies we can expect valid integers if they aren't blank.
                        # But let's be safe.
                        qty = 0 # Or handle error?

                if norm_item in data:
                    data[norm_item] += qty
                else:
                    data[norm_item] = qty

        # Prepare output
        output = []
        # Sort by normalized item name
        for item in sorted(data.keys()):
            output.append({"item": item, "quantity": data[item]})

        print(json.dumps(output))

    except Exception as e:
        # In a real environment, we might want to handle this differently
        # But for this task, we follow the spec.
        pass

if __name__ == "__main__":
    solve()
